/* Audit log failure handling, added 0.53.0.
   Before this fix, every write route did two non-transactional calls: saveLibrary() followed by
   appendChangeLog(). If the audit append threw, the route reported a 5xx even though the actual
   library write had already committed. The fix wraps appendChangeLog in a try/catch, logs the
   error to the console, and returns the normal success response with an optional warning field.
   This applies to all seven write routes: create, update, delete, settings, import, reset, restore.
*/
describe('audit log failure handling', () => {
  describe('create (POST /:collection)', () => {
    beforeEach(() => {
      vi.mocked(repo.getLibraryWithVersion).mockResolvedValue({ library: makeLibrary(), version: VERSION });
    });

    it('returns success with no warning when appendChangeLog succeeds', async () => {
      const res = await request(appAs(true)).post('/library/virtues').send({ Name: 'Resolve' });
      expect(res.status).toBe(200);
      expect(res.body.object.Name).toBe('Resolve');
      expect(res.body.warning).toBeUndefined();
      expect(repo.saveLibrary).toHaveBeenCalled();
    });

    it('returns success with warning when appendChangeLog throws', async () => {
      const appendError = Object.assign(new Error('Audit append failed'), { status: 500 });
      vi.mocked(repo.appendChangeLog).mockRejectedValue(appendError);

      const res = await request(appAs(true)).post('/library/virtues').send({ Name: 'Resolve' });
      expect(res.status).toBe(200);
      expect(res.body.warning).toBe('Audit log entry could not be written');
      expect(repo.saveLibrary).toHaveBeenCalled();
    });
  });

  describe('update (PUT /:collection/:id)', () => {
    beforeEach(() => {
      vi.mocked(repo.getLibraryWithVersion).mockResolvedValue({ library: makeLibrary(), version: VERSION });
    });

    it('returns success with no warning when appendChangeLog succeeds', async () => {
      const res = await request(appAs(true)).put('/library/virtues/v-might').send({ Tagline: 'Force' });
      expect(res.status).toBe(200);
      expect(res.body.object).toMatchObject({ Id: 'v-might', Name: 'Might', Tagline: 'Force' });
      expect(res.body.warning).toBeUndefined();
    });

    it('returns success with warning when appendChangeLog throws', async () => {
      const appendError = Object.assign(new Error('Audit append failed'), { status: 500 });
      vi.mocked(repo.appendChangeLog).mockRejectedValue(appendError);

      const res = await request(appAs(true)).put('/library/virtues/v-might').send({ Tagline: 'Force' });
      expect(res.status).toBe(200);
      expect(res.body.warning).toBe('Audit log entry could not be written');
    });
  });

  describe('delete (DELETE /:collection/:id)', () => {
