      expect(repo.saveLibrary).toHaveBeenCalled();
    });

    it('returns success with warning when appendChangeLog throws', async () => {
      const appendError = Object.assign(new Error('Audit append failed'), { status: 500 });
      vi.mocked(repo.appendChangeLog).mockRejectedValue(appendError);

      const res = await request(appAs(true)).put('/library/settings').send({ PotentialTrackLength: 9 });
      expect(res.status).toBe(200);
      expect(res.body.warning).toBe('Audit log entry could not be written');
      expect(repo.saveLibrary).toHaveBeenCalled();
    });
  });

  describe('import (POST /import)', () => {
