      expect(repo.saveLibrary).toHaveBeenCalledTimes(1);
    });
  });

  describe('restore (POST /changelog/:entryId/restore)', () => {
    const deleteEntry = {
      Id: 'cl-1',
      At: '2026-09-11T18:00:00.000Z',
      Who: 'Mike',
      Action: 'delete' as const,
      Collection: 'virtues',
